window.COFFEE = {
  API_URL: 'https://script.google.com/macros/s/AKfycbzCECsUCN3d2WOYvjkKZ56lgnYaqW1s1UhMs8ne6u_hzOpcHilgKgB7VaKeUNHwssdLzw/exec',
  DEFAULT_TASKS: [{"id": "o01", "block": "Открытие", "group": "o", "groupName": "Открытие · Стандарт (o01–o08)", "title": "📸 Фото-селфи", "instruction": "Фото перед началом смены.\n• Волосы аккуратно убраны в хвост или пучок.\n• Опрятный внешний вид, чистая рабочая форма и фартук.\n• Минимальный аккуратный макияж, отсутствие лишних украшений на руках.\n• Сделать селфи при хорошем освещении за баром.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 2, "mediaRequired": true}, {"id": "o02", "block": "Открытие", "group": "o", "groupName": "Открытие · Стандарт (o01–o08)", "title": "🪑 Зал и посадочные места", "instruction": "Подготовка гостевого зала к открытию:\n• Столы насухо протёрты от пыли и крошек дезинфицирующим средством.\n• Диваны и кресла устойчивы, обивка без пятен и мусора.\n• Декор на столах и полках выровнен по центру, свечи установлены.\n• Сделать обзорное фото чистого зала.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 3, "mediaRequired": true}, {"id": "o03", "block": "Открытие", "group": "o", "groupName": "Открытие · Стандарт (o01–o08)", "title": "☕ Кофемашина", "instruction": "Подготовка кофемашины к смене:\n• Кофемашина включена, бойлер вышел на рабочее давление и температуру.\n• Холдеры (портафильтры) чистые и прогретые, старый жмых полностью отсутствует.\n• Группы пролиты горячей водой и прогреты.\n• Хромированные детали и корпус натёрты микрофиброй до блеска, подтёки и накипь отсутствуют.", "photo": "да", "responsible": "Техник", "active": "да", "row": 4, "mediaRequired": true}, {"id": "o04", "block": "Открытие", "group": "o", "groupName": "Открытие · Стандарт (o01–o08)", "title": "⚙️ Гриндеры и Проверка помола", "instruction": "Настройка кофемолок (гриндеров) и эспрессо:\n• Гриндеры включены, бункеры заполнены свежим зерном.\n• Проверен и настроен помол: контрольный пролив эспрессо по весам и таймеру (проверка граммовки, времени экстракции и вкуса).\n• Зона вокруг дозатора и стол под гриндером очищены, остатки молотого кофе отсутствуют.\n• Зафиксировать утренние показания счётчика кофемашины.", "photo": "да", "responsible": "Шеф-бариста", "active": "да", "row": 5, "mediaRequired": true}, {"id": "o05", "block": "Открытие", "group": "o", "groupName": "Открытие · Стандарт (o01–o08)", "title": "🔥 Термопот", "instruction": "Проверка водонагревателя (термопота):\n• Включён в сеть, заполнен очищенной питьевой водой до отметки максимума.\n• Температура воды вышла на рабочий режим (92–95 °C).\n• Корпус и каплесборник чистые, без подтёков и накипи.", "photo": "нет", "responsible": "Техник", "active": "да", "row": 6, "mediaRequired": false}, {"id": "o06", "block": "Открытие", "group": "o", "groupName": "Открытие · Стандарт (o01–o08)", "title": "💡 Оборудование и подсветка", "instruction": "Включение света, звука и медиа:\n• Проектор, аудиоколонки (фоновая музыка на комфортной громкости) и декоративная подсветка включены.\n• Световая инсталляция и освещение у зеркала работают без мерцаний.", "photo": "нет", "responsible": "Техник", "active": "да", "row": 7, "mediaRequired": false}, {"id": "o07", "block": "Открытие", "group": "o", "groupName": "Открытие · Стандарт (o01–o08)", "title": "🌿 Летняя терраса Фото", "instruction": "Подготовка уличной зоны / летней террасы:\n• Уличные столы и стулья аккуратно расставлены по местам и насухо протёрты.\n• Пледы чистые, без пятен, аккуратно сложены.\n• Прилегающая территория и входная группа чистые, без мусора и листьев.\n• Сделать контрольное фото летней террасы.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 8, "mediaRequired": true}, {"id": "o08", "block": "Открытие", "group": "o", "groupName": "Открытие · Стандарт (o01–o08)", "title": "🧼 Санузел для гостей 📸 2", "instruction": "Важно !!! Полная утренняя проверка гостевого санузла (сделать 2 фото):\n• 🪞 Зеркало: протёрто средством для стёкол без разводов и следов пальцев, поверхность блестящая.\n• 🧻 Расходники: жидкое мыло в дозаторе в наличии, туалетная бумага и бумажные полотенца пополнены.\n• 🚽 Унитаз и бачок: чистые, обработаны, кнопка слива работает исправно, протечек нет, посторонний запах отсутствует.\n• 🗑 Мусорное ведро 📸: пустое, чистое, заправлен новый мусорный пакет.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 9, "mediaRequired": true}, {"id": "d01", "block": "День", "group": "d", "groupName": "День · Обход смены (d01–d06)", "title": "🌬️ Помещение проветрено и свежесть воздуха", "instruction": "Контроль микроклимата в зале:\n• Помещение проветрено, работает вентиляция или кондиционер по сезону.\n• Нет затхлого запаха, запаха гари или кухни, воздух в зале свежий и комфортный для гостей.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 10, "mediaRequired": false}, {"id": "d02", "block": "День", "group": "d", "groupName": "День · Обход смены (d01–d06)", "title": "☕ Оборудование проверено", "instruction": "Контроль работы барного оборудования в течение смены:\n• Кофемашина, кофемолка, чайник/термопот, холодильник и десертная витрина включены.\n• Все приборы держат рабочую температуру и работают штатно без аварийных сигналов и посторонних шумов.", "photo": "нет", "responsible": "Техник", "active": "да", "row": 11, "mediaRequired": false}, {"id": "d03", "block": "День", "group": "d", "groupName": "День · Обход смены (d01–d06)", "title": "🥛 Заготовки для напитков и молочные продукты", "instruction": "Контроль запасов и ротации (FIFO) в разгар дня:\n• Молоко обычное ≥ 5 л в запасе.\n• Альтернативное молоко ≥ 2 л.\n• Сливки ≥ 2 упаковок.\n• Сиропы, пюре и топпинги чистые, с дозаторами, стоят на своих местах.\n• Лёд в льдогенераторе готов в достаточном объёме.\n• 📸 Сделать фото холодильника в «подсобке» и фото холодильника за стойкой.", "photo": "да", "responsible": "Закупщик", "active": "да", "row": 12, "mediaRequired": true}, {"id": "d04", "block": "День", "group": "d", "groupName": "День · Обход смены (d01–d06)", "title": "🍰 Десерты и закуски", "instruction": "Контроль витрины с десертами:\n• Закуски и десерты пополнены и представлены в ДОСТАТОЧНОМ количестве.\n• Срок годности и маркировки актуальны, заветренных позиций нет.\n• Витрина чистая внутри и снаружи, фронтальное стекло без разводов и отпечатков.\n• Десерты и ценники выложены ровно и аккуратно 📸 (сделать фото витрины).", "photo": "да", "responsible": "Закупщик", "active": "да", "row": 13, "mediaRequired": true}, {"id": "d05", "block": "День", "group": "d", "groupName": "День · Обход смены (d01–d06)", "title": "🧼 Зона гостя и стойка на виду", "instruction": "Поддержание чистоты зоны выдачи и гостевой стойки:\n• Стойка и прилавок со стороны гостя идеально чистые: нет крошек, капель кофе, пятен и липких следов.\n• Грязная посуда со столов и стойки своевременно убрана в мойку.\n• Диспенсер с салфетками, крышками, трубочками и сахаром пополнен.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 14, "mediaRequired": true}, {"id": "d06", "block": "День", "group": "d", "groupName": "День · Обход смены (d01–d06)", "title": "🚽 Санузел проверен (2-3 сек видео) 📹", "instruction": "Дневная проверка санузла для гостей:\n• Санузел чистый, пол сухой, раковина и зеркало без брызг воды.\n• Туалетная бумага, мыло и бумажные полотенца в наличии.\n• Мусорное ведро не переполнено, запах свежий.\n• 📹 Сделать короткий обзорный видео-отчёт (2–3 секунды).", "photo": "да", "responsible": "Администратор", "active": "да", "row": 15, "mediaRequired": true}, {"id": "c01", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "🧴 Диспенсер с расходниками заполнен", "instruction": "Подготовка органайзера и расходников на утро:\n• Диспенсер полностью заполнен салфетками, порционным сахаром, трубочками и размешивателями (палочками).\n• Все открытые складские упаковки с расходниками плотно закрыты от пыли и влаги.", "photo": "да", "responsible": "Закупщик", "active": "да", "row": 16, "mediaRequired": true}, {"id": "c02", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "🪑 Зал и посадочные места", "instruction": "Уборка гостевого зала перед закрытием:\n• Все столы тщательно протёрты от крошек и пятен.\n• Диваны и стулья устойчивы, очищены щёткой/пылесосом от крошек.\n• Декор выровнен, пыль на полках и подоконниках отсутствует.\n• Все свечи в зале обязательно погашены.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 17, "mediaRequired": true}, {"id": "c03", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "☕ Кофемашина", "instruction": "Замывка и выключение кофемашины:\n• Проведена промывка групп со слепым фильтром и профессиональным средством (Cafiza), затем промывка чистой водой.\n• Холдеры и сита вымыты, кофейный жмых и масла полностью удалены, съёмные детали и решётка поддона промыты и установлены на место.\n• Стимеры (паровые трубки) очищены от молока и продуты.\n• Подтёков воды и накипи нет, хромированные детали натёрты насухо. Кофемашина выключена.", "photo": "да", "responsible": "Техник", "active": "да", "row": 18, "mediaRequired": true}, {"id": "c04", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "⚙️ Гриндеры", "instruction": "Очистка кофемолок и фиксация счётчиков:\n• Гриндеры протёрты снаружи и в зоне выдачи, остатки молотого кофе сметены кистью, устройства выключены.\n• Показания счётчиков порций кофемашины/гриндеров сняты и внесены в кассовый отчёт смены.", "photo": "да", "responsible": "Шеф-бариста", "active": "да", "row": 19, "mediaRequired": true}, {"id": "c05", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "🧽 Рабочая зона", "instruction": "Замывка барной станции:\n• Рабочая столешница и фартук вымыты с моющим средством и протёрты насухо.\n• Липких пятен от сиропов, молока и кофе нет.\n• Весь мелкий инвентарь (питчеры, темпер, коврик, весы) чистый и расставлен по местам.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 20, "mediaRequired": true}, {"id": "c06", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "🔥 Термопот", "instruction": "Отключение термопота:\n• Заполнен очищенной водой для утренней смены.\n• Питание выключено, корпус и каплесборник протёрты насухо, без подтёков.", "photo": "нет", "responsible": "Техник", "active": "да", "row": 21, "mediaRequired": false}, {"id": "c07", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "💰 Касса и терминалы Фото", "instruction": "Закрытие кассовой смены:\n• Наличные в кассе пересчитаны и сверены с отчётом.\n• Разменная сумма на утро оставлена в кассе в полном объёме (250 руб мелкими купюрами).\n• Фотоотчёт кассы сделан после подсчёта.\n• Банковский терминал и чековый принтер выключены, рабочий телефон поставлен на зарядку.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 22, "mediaRequired": true}, {"id": "c08", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "🍰 Холодильник и витрина", "instruction": "Уход за витриной и хранением десертов:\n• Подсветка витрины выключена (холодильный контур работает по регламенту), стёкла и полки протёрты.\n• Отпечатков пальцев и разводов на стекле нет.\n• Все десерты проверены по срокам, закрыты крышками/плёнкой от заветривания.", "photo": "да", "responsible": "Закупщик", "active": "да", "row": 23, "mediaRequired": true}, {"id": "c09", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "🪞 Зеркала и остекление", "instruction": "Натирка зеркал и входного остекления:\n• Зеркала в зале и стеклянные поверхности входной группы протёрты со средством для стёкол.\n• Разводов, брызг и следов пальцев нет, поверхности сухие.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 24, "mediaRequired": false}, {"id": "c10", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "💡 Оборудование и подсветка", "instruction": "Отключение иллюминации и медиа:\n• Проектор, неоновая/декоративная подсветка, аудиоколонки и дополнительное освещение выключены.\n• Световая инсталляция у зеркал и подсветка стола — выключены.", "photo": "нет", "responsible": "Техник", "active": "да", "row": 25, "mediaRequired": false}, {"id": "c11", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "🌿 Летняя терраса", "instruction": "Уборка летней террасы на ночь:\n• Уличные столы и стулья протёрты и занесены внутрь помещения (или зафиксированы по регламенту).\n• Пледы проверены (чистые, без пятен и прожогов) и аккуратно сложены на хранение.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 26, "mediaRequired": true}, {"id": "c12", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "🧼 Санузел для гостей", "instruction": "Полная вечерняя уборка санузла по чек-листу:\n• 🚻 Входная дверь — проверена исправность замка и доводчика; полотно двери и ручка протёрты, без следов рук.\n• 🧴 Раковина и смеситель — вымыты и вытерты насухо; смеситель натёрт без налёта и подтёков, вода не капает.\n• 🪞 Зеркало — протёрто без разводов и следов пальцев, поверхность блестящая.\n• 🧻 Расходники — проверен и пополнен запас жидкого мыла, туалетной бумаги и бумажных полотенец на утро.\n• 🚽 Унитаз и бачок — обработаны дезсредством, крышка опущена, бачок не протекает, запах отсутствует.\n• 🧹 Пол и стены — пол вымыт с дезсредством и высушен, плитка без пятен и налёта.\n• 🗑 Мусорное ведро — освобождено, вымыто, установлен новый пакет.\n• 💡 Освещение и вентиляция — свет и вытяжка выключены, проверена исправность выключателя.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 27, "mediaRequired": true}, {"id": "c13", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "🚪 Закрытие помещения", "instruction": "Финальная проверка перед выходом:\n• Все декоративные подсветки, сплит-система и барное оборудование (кроме холодильников) выключены.\n• Жалюзи / роллеты опущены, окна закрыты.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 28, "mediaRequired": false}, {"id": "c14", "block": "Закрытие", "group": "c", "groupName": "Закрытие · Стандарт (c01–c14)", "title": "🗑 Мусор выброшен, баки на улице пустые 📸💬", "instruction": "Вынос всего мусора из кофейни и уличных урн:\n• Все мусорные пакеты из-под бара, подсобки и санузла завязаны и вынесены в контейнер.\n• Уличные баки у входа очищены, внутрь вставлены чистые пакеты.\n• 📸 Сделать фото пустых баков и закрытой входной двери.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 29, "mediaRequired": true}, {"id": "pa01", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "📸 Фото-селфи 📸", "instruction": "Фото перед началом смены.\nВолосы убраны в хвост, аккуратный внешний вид, чистая форма, минимальный макияж.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 30, "mediaRequired": true}, {"id": "pa02", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🌿 Летняя терраса Фото📸", "instruction": "Столы и стулья расставлены, протёрты. Пледы чистые, сложены аккуратно, территория без мусора. Сделать фото.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 31, "mediaRequired": true}, {"id": "pa03", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🪑 Зал и посадочные места", "instruction": "Столы чистые, без крошек и пятен, диваны устойчивые, декор выровнен, пыль отсутствует, посадка полностью готова к приёму гостей.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 32, "mediaRequired": false}, {"id": "pa04", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "☕ Кофемашина + ☝️холдеры", "instruction": "Кофемашина включена и прогрета.\nСъёмные детали и чистые холдеры на месте.\nПодтёков воды и накипи нет, хромированные детали натёрты до блеска.", "photo": "да", "responsible": "Техник", "active": "да", "row": 33, "mediaRequired": true}, {"id": "pa05", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "⚙️ Гриндеры", "instruction": "Гриндеры протёрты, старые остатки кофе отсутствуют, помол проверен.\nУтренние показания счётчиков сверены и внесены в отчёт.", "photo": "нет", "responsible": "Шеф-бариста", "active": "да", "row": 34, "mediaRequired": false}, {"id": "pa06", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🧽 Рабочая зона и Мойка за стойкой", "instruction": "Рабочая поверхность вымыта и протёрта насухо, пятен от сиропов и кофе нет, порядок соблюдён.\nМойка за стойкой чистая, грязная посуда отсутствует.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 35, "mediaRequired": false}, {"id": "pa07", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🔥 Термопот", "instruction": "Заполнен очищенной водой, включён на прогрев, корпус сухой, без подтёков.", "photo": "нет", "responsible": "Техник", "active": "да", "row": 36, "mediaRequired": false}, {"id": "pa08", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "💰 Касса и терминалы", "instruction": "Разменная сумма в наличии (250 руб мелкими купюрами).\nТерминал и чековый принтер включены, рабочий телефон и планшет заряжены.\nВсё работает штатно, не зависает и блестит.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 37, "mediaRequired": false}, {"id": "pa09", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🧾 Кассовая лента Запас - 2шт.", "instruction": "Чековая лента установлена в принтер и терминал, в кассовой зоне в наличии минимум 2 запасных рулона.", "photo": "нет", "responsible": "Закупщик", "active": "да", "row": 38, "mediaRequired": false}, {"id": "pa10", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🍰 Холодильник и витрина", "instruction": "Холодильники и витрина чистые, продукты свежие, просрочки нет, открытое молоко закрыто крышками, товарное соседство и порядок соблюдены.", "photo": "нет", "responsible": "Закупщик", "active": "да", "row": 39, "mediaRequired": false}, {"id": "pa11", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "📦 Расходники барной зоны", "instruction": "Одноразовые стаканы всех объёмов, крышки, сахар, салфетки, трубочки и размешиватели заполнены до полной нормы.", "photo": "нет", "responsible": "Закупщик", "active": "да", "row": 40, "mediaRequired": false}, {"id": "pa12", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🍃 Заготовки", "instruction": "Ягодные/фруктовые заготовки, лимонады и основы свежие, промаркированы, без заветривания, полностью готовы к использованию.", "photo": "нет", "responsible": "Шеф-бариста", "active": "да", "row": 41, "mediaRequired": false}, {"id": "pa13", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🥛 Молоко", "instruction": "Молоко (обычное, безлактозное, альтернативное) с актуальным сроком годности, охлаждённое, закрытое, достаточный объём для смены.", "photo": "нет", "responsible": "Закупщик", "active": "да", "row": 42, "mediaRequired": false}, {"id": "pa14", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🍽 Посуда и инвентарь", "instruction": "Керамические чашки, стаканы, ложки, питчеры и барный инвентарь чистые, сухие, без сколов, в достаточном количестве.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 43, "mediaRequired": false}, {"id": "pa15", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🪞 Зеркала и остекление", "instruction": "Зеркала и витринные окна протёрты, разводов и следов пальцев нет, поверхности сухие и чистые.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 44, "mediaRequired": false}, {"id": "pa16", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "💡 Оборудование и подсветка", "instruction": "Освещение зала, проектор, колонки и неоновая подсветка исправны, включаются и работают корректно.", "photo": "нет", "responsible": "Техник", "active": "да", "row": 45, "mediaRequired": false}, {"id": "pa17", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🧼 Санузел", "instruction": "Гостевой санузел чистый, дезинфекция проведена, мыло, бумага и полотенца в наличии, полностью готов к использованию.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 46, "mediaRequired": false}, {"id": "pa18", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🛠 Декор и мебель", "instruction": "Столы, диваны, стулья и элементы декора целые, устойчивые, видимые повреждения отсутствуют.", "photo": "нет", "responsible": "Техник", "active": "да", "row": 47, "mediaRequired": false}, {"id": "pa19", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "⚙️ Оборудование и инвентарь", "instruction": "Всё барное и холодильное оборудование, блендер и льдогенератор исправны, в ремонте не нуждаются.", "photo": "нет", "responsible": "Техник", "active": "да", "row": 48, "mediaRequired": false}, {"id": "pa20", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "📦 Заявка", "instruction": "Складской запас и заявка поставщикам проверены, дефицита по ключевым позициям (зерно, молоко, стаканы, вода) нет.", "photo": "нет", "responsible": "Закупщик", "active": "да", "row": 49, "mediaRequired": false}, {"id": "pa21", "block": "Открытие", "group": "pa", "groupName": "Открытие · Приёмка смены (pa01–pa21)", "title": "🎯 Готовность точки", "instruction": "Кофейня полностью готова к открытию и приёму первых гостей без дополнительных действий.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 50, "mediaRequired": false}, {"id": "pe01", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🪑 Зал и посадочные места", "instruction": "Столы чистые, без крошек и пятен, диваны устойчивые, декор выровнен, пыль отсутствует, свечи погашены, посадка готова к приёму гостей.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 51, "mediaRequired": false}, {"id": "pe02", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "☕ Кофемашина", "instruction": "Холдеры вымыты, жмых удалён, съёмные элементы на месте, подтёков и накипи нет, оборудование выключено, зона вокруг чистая.", "photo": "да", "responsible": "Техник", "active": "да", "row": 52, "mediaRequired": true}, {"id": "pe03", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "⚙️ Гриндеры", "instruction": "Гриндеры чистые снаружи и в зоне дозатора, остатки кофе и пыль отсутствуют, выключены, показания счётчиков внесены.", "photo": "нет", "responsible": "Шеф-бариста", "active": "да", "row": 53, "mediaRequired": false}, {"id": "pe04", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🧽 Рабочая зона", "instruction": "Поверхности вымыты и вытерты насухо, пятна кофе, сиропов и молока отсутствуют, полки чистые, лишние предметы отсутствуют.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 54, "mediaRequired": false}, {"id": "pe05", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🔥 Термопот", "instruction": "Заполнен очищенной водой, выключен, корпус сухой, без подтёков.", "photo": "нет", "responsible": "Техник", "active": "да", "row": 55, "mediaRequired": false}, {"id": "pe06", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "💰 Касса и терминалы", "instruction": "Касса пересчитана, размен (250 руб мелкими купюрами) в наличии, фото сделано, терминал и принтер выключены, телефон на зарядке.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 56, "mediaRequired": true}, {"id": "pe07", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🧾 Кассовая лента", "instruction": "Запасная чековая лента (не менее 2 шт.) в наличии возле кассы.", "photo": "нет", "responsible": "Закупщик", "active": "да", "row": 57, "mediaRequired": false}, {"id": "pe08", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🍰 Холодильник и витрина", "instruction": "Чистые внутри и снаружи, остатки еды отсутствуют, продукты разложены аккуратно, открытое молоко закрыто, просрочки нет, заветренные продукты списаны.", "photo": "нет", "responsible": "Закупщик", "active": "да", "row": 58, "mediaRequired": false}, {"id": "pe09", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🌡 Температурный режим", "instruction": "Температура холодильника и витрины проверена по дисплею и соответствует норме (+2…+6 °C).", "photo": "нет", "responsible": "Техник", "active": "да", "row": 59, "mediaRequired": false}, {"id": "pe10", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🧴 Сиропы и ингредиенты", "instruction": "Бутылки с сиропами, топпинги и помпы протёрты от липкости, закрыты, стоят по местам в достаточном количестве.", "photo": "нет", "responsible": "Закупщик", "active": "да", "row": 60, "mediaRequired": false}, {"id": "pe11", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🪞 Зеркала и остекление", "instruction": "Все зеркала и витринные стёкла чистые, без разводов и следов пальцев.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 61, "mediaRequired": false}, {"id": "pe12", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "💡 Оборудование и подсветка", "instruction": "Всё освещение зала, проектор, декоративная подсветка и колонки выключены.", "photo": "нет", "responsible": "Техник", "active": "да", "row": 62, "mediaRequired": false}, {"id": "pe13", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🌿 Летняя терраса", "instruction": "Уличная мебель чистая и занесена внутрь, пледы аккуратно сложены.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 63, "mediaRequired": false}, {"id": "pe14", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🚪 Помещение", "instruction": "Жалюзи опущены, окна закрыты, климатическое и неиспользуемое ночью оборудование выключено.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 64, "mediaRequired": false}, {"id": "pe15", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🧼 Санузел", "instruction": "Санузел чистый, полотенца заменены, расходники пополнены, посторонний запах отсутствует.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 65, "mediaRequired": false}, {"id": "pe16", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "📦 Расходники барной зоны", "instruction": "Стаканы, крышки, сахар, салфетки, трубочки и мешалки пополнены до полной утренней нормы.", "photo": "нет", "responsible": "Закупщик", "active": "да", "row": 66, "mediaRequired": false}, {"id": "pe17", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🍃 Заготовки", "instruction": "Заготовки свежие, без заветривания и порчи, испорченные позиции списаны и внесены в отчёт, всё подготовлено к следующей смене.", "photo": "нет", "responsible": "Шеф-бариста", "active": "да", "row": 67, "mediaRequired": false}, {"id": "pe18", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🥛 Молоко 📸", "instruction": "Все открытые пачки молока плотно закрыты крышками, хранятся в холодильнике корректно, просрочки нет. Сделать фото запаса молока.", "photo": "да", "responsible": "Закупщик", "active": "да", "row": 68, "mediaRequired": true}, {"id": "pe19", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🧴 Полотенца", "instruction": "Чистые рабочие полотенца и микрофибры подготовлены на утро, использованные убраны в стирку.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 69, "mediaRequired": false}, {"id": "pe20", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🍽 Посуда и инвентарь", "instruction": "Вся посуда чистая, питчеры и кувшины вымыты насухо, достаточный запас чашек, блюдец и ложек подготовлен к утренней смене.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 70, "mediaRequired": false}, {"id": "pe21", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🧹 Чистота инвентаря и хранения", "instruction": "Грязная посуда в мойке отсутствует, полки и складские зоны хранения чистые и приведены в порядок.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 71, "mediaRequired": false}, {"id": "pe22", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "📦 Заявка", "instruction": "Заявка на пополнение продуктов и хозтоваров сформирована по остаткам и отправлена закупщику/руководителю.", "photo": "нет", "responsible": "Закупщик", "active": "да", "row": 72, "mediaRequired": false}, {"id": "pe23", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🛠 Декор и мебель", "instruction": "Декор и мебель в зале целые, расставлены ровно, повреждения отсутствуют.", "photo": "нет", "responsible": "Техник", "active": "да", "row": 73, "mediaRequired": false}, {"id": "pe24", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "⚙️ Оборудование и инвентарь", "instruction": "Всё оборудование и барный инвентарь исправны, в ремонте не нуждаются (обо всех поломках сообщено через кнопку «Поломка»).", "photo": "нет", "responsible": "Техник", "active": "да", "row": 74, "mediaRequired": false}, {"id": "pe25", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🗑 Мусор выброшен, баки на улице пустые 📸💬", "instruction": "Весь мусор из кофейни и уличных урн вынесен в контейнеры, баки чистые, заправлены новые мешки. Сделать фото.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 75, "mediaRequired": true}, {"id": "pe26", "block": "Закрытие", "group": "pe", "groupName": "Закрытие · Полная сдача (pe01–pe26)", "title": "🎯 Готовность точки", "instruction": "Бар и зал полностью готовы к утреннему открытию и работе без дополнительных действий.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 76, "mediaRequired": false}, {"id": "u01", "block": "Закрытие", "group": "u", "groupName": "Закрытие · Уборка помещения (u01–u07)", "title": "🗑️ Уличная мусорка очищена, мусор вынесен", "instruction": "Очистка уличной урны у входа:\n• Весь мусор из уличной мусорки полностью вынесен в общий контейнер.\n• Внутренняя ёмкость чистая, новый плотный мусорный пакет аккуратно вставлен и закреплён.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 77, "mediaRequired": true}, {"id": "u02", "block": "Закрытие", "group": "u", "groupName": "Закрытие · Уборка помещения (u01–u07)", "title": "🚪🧼 Крыльцо очищено и вымыто 📸", "instruction": "Уборка входной группы и крыльца:\n• Ступени и площадка крыльца подметены от песка, пыли и листьев.\n• Выполнена влажная мойка крыльца и придверного коврика, следов грязи и пятен нет.\n• 📸 Сделать фото чистого крыльца.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 78, "mediaRequired": true}, {"id": "u03", "block": "Закрытие", "group": "u", "groupName": "Закрытие · Уборка помещения (u01–u07)", "title": "🚪 Входная дверь натёрта, без следов и пятен", "instruction": "Чистка входной двери:\n• Стекло входной двери с обеих сторон натёрто средством для стёкол без разводов и отпечатков рук.\n• Дверная ручка, профиль и порог протёрты влажной, затем сухой салфеткой.", "photo": "нет", "responsible": "Администратор", "active": "да", "row": 79, "mediaRequired": false}, {"id": "u04", "block": "Закрытие", "group": "u", "groupName": "Закрытие · Уборка помещения (u01–u07)", "title": "🪟 Зеркала и Стёкла натёрты, без разводов и загрязнений 📸", "instruction": "Мойка зеркал и витринных стёкол:\n• Все зеркала в зале, у фотозоны и в санузле натёрты микрофиброй со средством для стёкол.\n• Подтёков, разводов и следов пальцев нет.\n• 📸 Сделать контрольное фото.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 80, "mediaRequired": true}, {"id": "u05", "block": "Закрытие", "group": "u", "groupName": "Закрытие · Уборка помещения (u01–u07)", "title": "🛋️ Диваны отодвинуты, выполнена влажная уборка полов под диванами 📸", "instruction": "Важно!!! ☝️ ☝️ ☝️\n• Аккуратно отодвинуть диваны от стен, подмести крошки и пыль, тщательно вымыть пол и плинтусы под диванами, затем ровно вернуть диваны на место.\n• Регулярно менять грязную воду в ведре на чистую.\n• Выливать грязную воду ТОЛЬКО на улице в отведённое место (категорически запрещено выливать в мойку в подсобке — слив забивается песком!).\n• 📸 Сделать фото чистого пола под диванами.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 81, "mediaRequired": true}, {"id": "u06", "block": "Закрытие", "group": "u", "groupName": "Закрытие · Уборка помещения (u01–u07)", "title": "🧹 Влажная уборка полов в зале", "instruction": "Финальная мойка полов:\n• Пол во всём гостевом зале, за барной стойкой и в проходах подметён и тщательно вымыт с моющим средством.\n• Углы и плинтусы чистые, без разводов и липких следов.\n• Грязная вода после уборки вылита на улице, моп/тряпка промыты и поставлены на просушку.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 82, "mediaRequired": true}, {"id": "u07", "block": "Закрытие", "group": "u", "groupName": "Закрытие · Уборка помещения (u01–u07)", "title": "🚽 Туалет вымыт и продезинфицирован 📸 (видео 5-7 сек)", "instruction": "Финальная дезинфекция санузла:\n• Унитаз, раковина, смеситель, дверные ручки и пол вымыты и обработаны дезинфицирующим средством.\n• Мусор выброшен, вставлен чистый пакет, расходники пополнены на утро.\n• 📹 Снять обзорное видео чистого санузла (5–7 секунд).", "photo": "да", "responsible": "Администратор", "active": "да", "row": 83, "mediaRequired": true}, {"id": "q01", "block": "День", "group": "q", "groupName": "День · Чистка До/После (q01–q09)", "title": "☕ Кофемашина (фото до и после)", "instruction": "• Корпус протёрт, без пятен, подтёков и кофейных следов.\n• Группы промыты, остатки кофе отсутствуют.\n• Портафильтры вымыты, без кофейных масел и налёта.\n• Паровые трубки очищены и продуты.\n• Поддон и решётка вымыты, без остатков воды и кофе.\n• Поверхности вокруг чистые, без кофейной гущи.\n• 📸 Сделать фото ДО и ПОСЛЕ чистки.", "photo": "да", "responsible": "Техник", "active": "да", "row": 84, "mediaRequired": true}, {"id": "q02", "block": "День", "group": "q", "groupName": "День · Чистка До/После (q01–q09)", "title": "🌪 Блендер (фото до и после)", "instruction": "• Чаша блендера вымыта, без остатков продуктов, налёта и запахов.\n• Ножи чистые, промыты со всех сторон.\n• Крышка и уплотнитель вымыты, без загрязнений в пазах.\n• Корпус и панель кнопок протёрты насухо, без капель и липкости.\n• 📸 Сделать фото ДО и ПОСЛЕ чистки.", "photo": "да", "responsible": "Техник", "active": "да", "row": 85, "mediaRequired": true}, {"id": "q03", "block": "День", "group": "q", "groupName": "День · Чистка До/После (q01–q09)", "title": "❄️ Холодильник под стойкой (фото до и после)", "instruction": "• Полки и стенки чистые, без крошек, пятен молока и подтёков.\n• Продукты и молоко размещены аккуратно по срокам годности.\n• Посторонние запахи отсутствуют.\n• Резиновые уплотнители дверцы вымыты в складках.\n• Дверца закрывается плотно.\n• 📸 Сделать фото ДО и ПОСЛЕ чистки.", "photo": "да", "responsible": "Закупщик", "active": "да", "row": 86, "mediaRequired": true}, {"id": "q04", "block": "День", "group": "q", "groupName": "День · Чистка До/После (q01–q09)", "title": "📦 Холодильник склад (фото до и после)", "instruction": "• Полки чистые, без загрязнений и подтёков.\n• Продукты разложены строго по категориям и промаркированы.\n• Посторонние запахи отсутствуют.\n• Уплотнители чистые, дверца закрывается плотно.\n• 📸 Сделать фото ДО и ПОСЛЕ чистки.", "photo": "да", "responsible": "Закупщик", "active": "да", "row": 87, "mediaRequired": true}, {"id": "q05", "block": "День", "group": "q", "groupName": "День · Чистка До/После (q01–q09)", "title": "🧊 Морозилка верхняя (фото до и после)", "instruction": "• Внутренняя камера очищена, без снежной наледи, крошек и загрязнений.\n• Замороженные заготовки и продукты упакованы, подписаны и размещены аккуратно.\n• Уплотнитель чистый, дверца закрывается плотно.\n• 📸 Сделать фото ДО и ПОСЛЕ чистки.", "photo": "да", "responsible": "Закупщик", "active": "да", "row": 88, "mediaRequired": true}, {"id": "q06", "block": "День", "group": "q", "groupName": "День · Чистка До/После (q01–q09)", "title": "🧊 Морозилка нижняя (фото до и после)", "instruction": "• Внутри чисто, ящики/полки вымыты без крошек и остатков продуктов.\n• Продукты расфасованы и размещены аккуратно.\n• Посторонние запахи отсутствуют.\n• 📸 Сделать фото ДО и ПОСЛЕ чистки.", "photo": "да", "responsible": "Закупщик", "active": "да", "row": 89, "mediaRequired": true}, {"id": "q07", "block": "День", "group": "q", "groupName": "День · Чистка До/После (q01–q09)", "title": "🧊 Льдогенератор (фото до и после)", "instruction": "• Внутренняя камера чистая, без слизи, плесени и известкового налёта.\n• Лёд прозрачный, без постороннего запаха, совок для льда чистый.\n• Лоток и дренаж чистые, без застоя воды.\n• Корпус снаружи и вентиляционная решётка протёрты.\n• 📸 Сделать фото ДО и ПОСЛЕ чистки.", "photo": "да", "responsible": "Техник", "active": "да", "row": 90, "mediaRequired": true}, {"id": "q08", "block": "День", "group": "q", "groupName": "День · Чистка До/После (q01–q09)", "title": "🚰 Мойка склад (фото до и после)", "instruction": "• Раковина на складе вымыта с дезсредством, без жира, налёта и остатков пищи.\n• Сливная сеточка и сифон чистые, без засоров и запаха (песок с полов в мойку не сливать!).\n• Смеситель натёрт без водного камня.\n• Поверхности и фартук вокруг мойки чистые и сухие.\n• 📸 Сделать фото ДО и ПОСЛЕ чистки.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 91, "mediaRequired": true}, {"id": "q09", "block": "День", "group": "q", "groupName": "День · Чистка До/После (q01–q09)", "title": "🚰 Мойка стойка (фото до и после)", "instruction": "• Барная раковина и ринзер чистые, без остатков молока и кофейной гущи.\n• Слив чистый, вода уходит быстро, запах отсутствует.\n• Смеситель натёрт до блеска без налёта.\n• Рабочая зона вокруг мойки сухая и чистая.\n• 📸 Сделать фото ДО и ПОСЛЕ чистки.", "photo": "да", "responsible": "Администратор", "active": "да", "row": 92, "mediaRequired": true}],
  SAMPLE_INC_PHOTO: "data:image/svg+xml;base64,"
};

